import { describe, test } from "node:test";
import assert from "node:assert/strict";
import { createHash } from "node:crypto";
import { readFileSync } from "node:fs";
import * as atom from "./atom/index.ts";
import * as bytes from "../runtime/bytes.ts";
import * as conv from "../runtime/conv.ts";
import { ElementNode, Node } from "./node.ts";
import { Parse, ParseFragment, ParseWithOptions, ParseOptionEnableScripting } from "./parse.ts";
import { Render } from "./render.ts";

// Vectors are generated by ts/tools/gen-html-vectors (command "parse") from Go's real
// html package (Parse, ParseFragment, ParseWithOptions, Render).
//
// File layout: "records" is the table of distinct run records. A record is one of
//   ["f", tree, render]                      full mode, optionally followed by err, renderErr
//   ["h", treeSha, treeLen, renderSha, renderLen]   hash mode, optionally followed by err, renderErr
//   ["p", message]                           Go panics on this run
// A document has the index of its Parse record, one index per context (null when the
// context is not run for the document), and the index of its noscript record or null.
//
// The tree of a run is the list of its nodes. Parse returns [document]. A node is
// [type, data, dataAtom, namespace, [[namespace, key, value], ...], [children...]].
// The canonical dump of a list of nodes is the JSON text of the same structure with the
// keys of the object form (see canonNode), with no whitespace; a hash is taken over its
// UTF-8 bytes. The rendered bytes of a run are Render of each node, one buffer, stopping at
// the first error.
//
// Strings in Go are compared as JS strings for valid UTF-8 input, byte for byte. Invalid
// UTF-8 input is a separate group: a JS string cannot hold invalid bytes, so Go's output is
// stored after conv.StringFromBytes, and the rendered bytes are compared with
// conv.BytesFromString(conv.StringFromBytes(bytes)).

interface Doc {
  name: string;
  valid: boolean;
  input: string | { hex: string };
  mode: "full" | "hash";
  parse: number;
  frag: (number | null)[];
  noscript: number | null;
}

interface ParseVectors {
  goVersion: string;
  corpus: number;
  contexts: string[];
  records: unknown[][];
  docs: Doc[];
}

const vectors: ParseVectors = JSON.parse(
  readFileSync(new URL("./testdata/parse_vectors.json", import.meta.url), "utf8")
);

// contextNodes gives the context element of each name in vectors.contexts, built as in the
// Go generator.
const contextNodes: Record<string, [atom.Atom, string]> = {
  body: [atom.Body, ""],
  div: [atom.Div, ""],
  p: [atom.P, ""],
  table: [atom.Table, ""],
  tbody: [atom.Tbody, ""],
  tr: [atom.Tr, ""],
  td: [atom.Td, ""],
  select: [atom.Select, ""],
  ul: [atom.Ul, ""],
  script: [atom.Script, ""],
  textarea: [atom.Textarea, ""],
  title: [atom.Title, ""],
  svg: [atom.Svg, "svg"],
  math: [atom.Math, "math"],
  template: [atom.Template, ""],
  html: [atom.Html, ""],
  head: [atom.Head, ""],
  frameset: [atom.Frameset, ""],
};

// bytesOf returns a fresh array with the bytes of a stored input.
function bytesOf(v: string | { hex: string }): Uint8Array {
  if (typeof v === "string") {
    return conv.BytesFromString(v);
  }
  const out = new Uint8Array(v.hex.length / 2);
  for (let i = 0; i < out.length; i++) {
    out[i] = parseInt(v.hex.slice(2 * i, 2 * i + 2), 16);
  }
  return out;
}

// canonStr writes s as a JSON string. Only '"', '\' and the control characters below 0x20
// are escaped (as \u00xx, lowercase hex). JSON.stringify is not used, because it escapes
// other control characters differently.
function canonStr(s: string): string {
  let out = '"';
  for (let i = 0; i < s.length; i++) {
    const c = s.charCodeAt(i);
    if (c === 0x22) {
      out += '\\"';
    } else if (c === 0x5c) {
      out += "\\\\";
    } else if (c < 0x20) {
      out += "\\u00" + c.toString(16).padStart(2, "0");
    } else {
      out += s[i];
    }
  }
  return out + '"';
}

// canonNode is the canonical dump of one node (see the header of this file).
function canonNode(n: Node): string {
  const attrs = n.Attr.map((a) => "[" + canonStr(a.Namespace) + "," + canonStr(a.Key) + "," + canonStr(a.Val) + "]");
  const kids: string[] = [];
  for (let c = n.FirstChild; c !== null; c = c.NextSibling) {
    kids.push(canonNode(c));
  }
  return (
    '{"t":' +
    n.Type +
    ',"d":' +
    canonStr(n.Data) +
    ',"a":' +
    n.DataAtom +
    ',"n":' +
    canonStr(n.Namespace) +
    ',"at":[' +
    attrs.join(",") +
    '],"c":[' +
    kids.join(",") +
    "]}"
  );
}

// canonList is the canonical dump of a list of nodes.
function canonList(nodes: Node[]): string {
  return "[" + nodes.map(canonNode).join(",") + "]";
}

// nodeVal is the nested-array form of a node, as stored in the vectors.
function nodeVal(n: Node): unknown[] {
  const kids: unknown[] = [];
  for (let c = n.FirstChild; c !== null; c = c.NextSibling) {
    kids.push(nodeVal(c));
  }
  return [
    n.Type,
    n.Data,
    n.DataAtom,
    n.Namespace,
    n.Attr.map((a) => [a.Namespace, a.Key, a.Val]),
    kids,
  ];
}

function sha256Hex(b: Uint8Array): string {
  return createHash("sha256").update(b).digest("hex");
}

// verifyRun checks one run against its record. produce runs the port; a record with "p"
// requires produce to throw, as the Go panic does.
function verifyRun(label: string, rec: unknown[], produce: () => [Node[], Error | null]): void {
  if (rec[0] === "p") {
    assert.throws(produce, Error, label + ": Go panics here, the port must throw");
    return;
  }
  const [nodes, err] = produce();
  const buf = new bytes.Buffer();
  let renderErr: string | null = null;
  for (const n of nodes) {
    const e = Render(buf, n);
    if (e !== null) {
      renderErr = e.message;
      break;
    }
  }
  // The rendered bytes are valid UTF-8 (they come from JS strings), so the lossy step is the identity here.
  const rb = conv.BytesFromString(conv.StringFromBytes(buf.Bytes()));
  const canon = canonList(nodes);
  const canonBytes = conv.BytesFromString(canon);

  if (rec[0] === "f") {
    assert.deepEqual(nodes.map(nodeVal), rec[1], label + ": tree");
    assert.equal(conv.StringFromBytes(rb), rec[2], label + ": rendered bytes");
  } else {
    assert.equal(sha256Hex(canonBytes), rec[1], label + ": tree hash");
    assert.equal(canonBytes.length, rec[2], label + ": tree length");
    assert.equal(sha256Hex(rb), rec[3], label + ": rendered hash");
    assert.equal(rb.length, rec[4], label + ": rendered length");
  }
  const errAt = rec[0] === "f" ? 3 : 5;
  if (rec.length > errAt) {
    assert.equal(err === null ? null : err.message, rec[errAt], label + ": error");
    assert.equal(renderErr, rec[errAt + 1], label + ": render error");
  } else {
    assert.equal(err, null, label + ": unexpected error");
    assert.equal(renderErr, null, label + ": unexpected render error");
  }
}

// checkDoc checks every run of one document: Parse, each context that is stored, and the
// noscript run.
function checkDoc(d: Doc): void {
  const rec = (i: number): unknown[] => vectors.records[i];
  verifyRun(d.name + " parse", rec(d.parse), (): [Node[], Error | null] => {
    const [doc, err] = Parse(bytesOf(d.input));
    return [doc === null ? [] : [doc], err];
  });
  d.frag.forEach((idx, i) => {
    if (idx === null) {
      return;
    }
    const ctxName = vectors.contexts[i];
    const [tag, ns] = contextNodes[ctxName];
    verifyRun(d.name + " context " + ctxName, rec(idx), (): [Node[], Error | null] => {
      const ctx = Object.assign(new Node(), { Type: ElementNode, DataAtom: tag, Data: ctxName, Namespace: ns });
      return ParseFragment(bytesOf(d.input), ctx);
    });
  });
  if (d.noscript !== null) {
    verifyRun(d.name + " noscript", rec(d.noscript), (): [Node[], Error | null] => {
      const [doc, err] = ParseWithOptions(bytesOf(d.input), ParseOptionEnableScripting(false));
      return [doc === null ? [] : [doc], err];
    });
  }
}

describe("parse vectors: valid UTF-8 documents (byte for byte)", () => {
  for (const d of vectors.docs) {
    if (d.valid) {
      test(d.name, () => checkDoc(d));
    }
  }
});

describe("parse vectors: invalid UTF-8 documents (lossy, see the header)", () => {
  for (const d of vectors.docs) {
    if (!d.valid) {
      test(d.name, () => checkDoc(d));
    }
  }
});
